from taf.gnb.oam.coam.admin.schemas.procedure.ccm_uplink import CCMUplink


class CCMUplinkPusch(CCMUplink):
    def __init__(self, nrcell_rdn, nrarfcn_ul, reporting_time_interval, beam_pattern_id, performance_test_type,
                 frc_index, prb_offset, digital_out_type, digital_out_rate, ru_mode, phys_cell_id,
                 ul_dmrs_mapping_type, is_ptrs_fr2_enabled, bb_selector=None):
        super(CCMUplinkPusch, self).__init__(nrcell_rdn=nrcell_rdn,
                                             nrarfcn_ul=nrarfcn_ul,
                                             reporting_time_interval=reporting_time_interval,
                                             beam_pattern_id=beam_pattern_id,
                                             performance_test_type=performance_test_type,
                                             ru_mode=ru_mode,
                                             phys_cell_id=phys_cell_id)
        self.pusch_params = {"frcIndex": self.validate_param('frcIndex',
                                                             frc_index,
                                                             (frc_index in (
                                                                 'G_FR1_A3_1', 'G_FR1_A3_2', 'G_FR1_A3_3',
                                                                 'G_FR1_A3_5', 'G_FR1_A3_6', 'G_FR1_A3_7',
                                                                 'G_FR1_A3_8', 'G_FR1_A3_9', 'G_FR1_A3_10',
                                                                 'G_FR1_A3_12', 'G_FR1_A3_13', 'G_FR1_A3_14',
                                                                 'G_FR1_A3_15', 'G_FR1_A3_16', 'G_FR1_A3_17',
                                                                 'G_FR1_A3_17', 'G_FR1_A3_19', 'G_FR1_A3_20',
                                                                 'G_FR1_A3_21', 'G_FR1_A3_22', 'G_FR1_A3_23',
                                                                 'G_FR1_A3_24', 'G_FR1_A3_26', 'G_FR1_A3_27',
                                                                 'G_FR1_A3_28', 'G_FR1_A4', 'G_FR1_A4_1',
                                                                 'G_FR1_A4_2', 'G_FR1_A4_3', 'G_FR1_A4_6',
                                                                 'G_FR1_A4_7', 'G_FR1_A4_8', 'G_FR1_A4_9',
                                                                 'G_FR1_A4_10', 'G_FR1_A4_12', 'G_FR1_A4_13',
                                                                 'G_FR1_A4_14', 'G_FR1_A4_15', 'G_FR1_A4_16',
                                                                 'G_FR1_A4_17', 'G_FR1_A4_19', 'G_FR1_A4_20',
                                                                 'G_FR1_A4_21', 'G_FR1_A4_22', 'G_FR1_A4_23',
                                                                 'G_FR1_A4_24', 'G_FR1_A4_26', 'G_FR1_A4_27',
                                                                 'G_FR1_A4_28', 'G_FR1_A5_1', 'G_FR1_A5_2',
                                                                 'G_FR1_A5_3', 'G_FR1_A5_5', 'G_FR1_A5_6',
                                                                 'G_FR1_A5_7', 'G_FR1_A5_8', 'G_FR1_A5_9',
                                                                 'G_FR1_A5_10', 'G_FR1_A5_12', 'G_FR1_A5_13',
                                                                 'G_FR1_A5_14', 'G_FR2_A3_4', 'G_FR2_A3_9',
                                                                 'G_FR2_A4_4', 'G_FR2_A4_9', 'G_FR2_A5_4'))
                                                             ),
                             "prbOffset": self.validate_param('prbOffset',
                                                              prb_offset,
                                                              (0 <= prb_offset <= 273)),
                             "digitalOutType": self.validate_param('digitalOutType',
                                                                   digital_out_type,
                                                                   (digital_out_type in ("SerialKeysight",
                                                                                         "SerialRs"))),
                             "digitalOutRate": self.validate_param('digitalOutRate',
                                                                   digital_out_rate,
                                                                   (digital_out_rate in ("Bitrate_115dot2K",
                                                                                         "Bitrate_1dot92M",
                                                                                         "Bitrate_460dot8K"))),
                             "bbSelector": self.validate_param('bbSelector',
                                                               bb_selector,
                                                               (bb_selector is None or (0 <= bb_selector <= 3))),
                             "ulDmrsMappingType": self.validate_param('ulDmrsMappingType',
                                                                      ul_dmrs_mapping_type,
                                                                      (ul_dmrs_mapping_type in ("A", "B"))),
                             "isPtrsFr2Enabled": self.validate_param('isPtrsFr2Enabled',
                                                                     is_ptrs_fr2_enabled,
                                                                     (is_ptrs_fr2_enabled in (True, False)))}

    @classmethod
    def from_response_dict(cls, response_dict):
        def _get_pusch_param(parameter):
            return response_dict['params']['puschParams'][parameter]

        def _get_optional_param(test_type, parameter):
            return response_dict['params'][test_type][parameter] \
                if parameter in response_dict['params'][test_type] else None

        nrcell_rdn = response_dict['nrcell_rDN']
        nrarfcn_ul = response_dict['params']['nrarfcnUl'] if 'nrarfcnUl' in response_dict['params'] else None
        reporting_time_interval = response_dict['params']['reportingTimeInterval']
        beam_pattern_id = response_dict['params']['beamPatternId']
        performance_test_type = response_dict['params']['performanceTestType']
        ru_mode = response_dict['params']['ruMode']
        phys_cell_id = response_dict['params']['physCellId']

        pusch_params = {"frcIndex": _get_pusch_param('frcIndex'),
                        "prbOffset": _get_pusch_param('prbOffset'),
                        "digitalOutType": _get_pusch_param('digitalOutType'),
                        "digitalOutRate": _get_pusch_param('digitalOutRate'),
                        "bbSelector": _get_optional_param('puschParams', 'bbSelector'),
                        "ulDmrsMappingType": _get_pusch_param('ulDmrsMappingType'),
                        "isPtrsFr2Enabled": _get_pusch_param('isPtrsFr2Enabled')}

        return cls(nrcell_rdn=nrcell_rdn,
                   nrarfcn_ul=nrarfcn_ul,
                   reporting_time_interval=reporting_time_interval,
                   beam_pattern_id=beam_pattern_id,
                   performance_test_type=performance_test_type,
                   ru_mode=ru_mode,
                   phys_cell_id=phys_cell_id,
                   frc_index=pusch_params['frcIndex'],
                   prb_offset=pusch_params['prbOffset'],
                   digital_out_type=pusch_params['digitalOutType'],
                   digital_out_rate=pusch_params['digitalOutRate'],
                   ul_dmrs_mapping_type=pusch_params['ulDmrsMappingType'],
                   is_ptrs_fr2_enabled=pusch_params['isPtrsFr2Enabled'],
                   bb_selector=pusch_params['bbSelector'])

    def as_dict(self):
        attributes = super(CCMUplinkPusch, self).as_dict()
        self.pusch_params = self._remove_empty_params(self.pusch_params)
        attributes['params']['puschParams'] = self.pusch_params

        return attributes

    @staticmethod
    def _remove_empty_params(params):
        return {k: v for k, v in params.items() if v is not None}
